import { NativeFunction } from '~/shared/constants/native-function';

export const usePhoneCall = () => {
  const openPhoneCall = (phoneNumber: string) => {
    if (!window.ReactNativeWebView) {
      window.open(`tel:${phoneNumber}`);
      return;
    }

    window.webViewBridge.send(NativeFunction.PhoneCall, phoneNumber);
  };

  return { openPhoneCall };
};
